    "template": "(args = {}) => {\n    const join = (xs) => (xs || []).filter(Boolean).join(\"\\n\");\n    const lines = (v) => String(v || \"\").split(/\\n+/).map(function(s){ return s.trim(); }).filter(Boolean);\n    const {\n      icp, job, channel,\n      promise, picture, proof_metrics, proof_logos, proof_badges, proof_links,\n      push_cta, push_target, push_urgency,\n      promise_b, push_b,\n      style_notes, compliance, qa_on, tracking,\n      output_pref\n    } = args;\n\n    const mode = {\n      \"Outline only\": 1,\n      \"Table + labels\": 2,\n      \"Full working canvas\": 3\n    }[output_pref] || 2;\n\n    const header = join([\n      \"4Ps: Promise – Picture – Proof – Push\",\n      \"What it is: a four-beat persuasive sequence used in direct-response and modern product marketing.\",\n      icp && (\"ICP: \" + icp),\n      job && (\"Job to be done: \" + job),\n      channel && (\"Channel: \" + channel)\n    ]);\n\n    const promiseBlock = join([\n      \"Promise\",\n      promise || \"(Outcome in the reader’s words; avoid feature-speak.)\"\n    ]);\n\n    const pictureBlock = join([\n      \"Picture\",\n      picture || \"(One concrete scene. If a camera followed them next Tuesday, what would it capture.)\"\n    ]);\n\n    const proofBlock = join([\n      \"Proof\",\n      (lines(proof_metrics).length && (\"Metrics:\\n- \" + lines(proof_metrics).join(\"\\n- \"))) || null,\n      (lines(proof_logos).length && (\"Logos or named customers:\\n- \" + lines(proof_logos).join(\"\\n- \"))) || null,\n      (lines(proof_badges).length && (\"Badges and certifications:\\n- \" + lines(proof_badges).join(\"\\n- \"))) || null,\n      (lines(proof_links).length && (\"Links and clips:\\n- \" + lines(proof_links).join(\"\\n- \"))) || null\n    ]);\n\n    const pushLine = join([\n      push_cta || \"(One CTA)\",\n      push_target ? (\" → \" + push_target) : null,\n      push_urgency ? (\" [\" + push_urgency + \"]\") : null\n    ]);\n    const pushBlock = join([\n      \"Push\",\n      pushLine || \"(Give one specific, time-bound next step.)\"\n    ]);\n\n    const variants = ((promise_b || push_b) ? join([\n      \"# Variants for testing\",\n      promise_b && (\"Promise B: \" + promise_b),\n      push_b && (\"Push B: \" + push_b),\n      \"Test first on Promise and Push; they usually swing the most.\"\n    ]) : null);\n\n    const channelScaffolds = {\n      \"Landing page\": join([\n        \"# Landing page scaffold\",\n        \"Hero – Promise:\",\n        promise || \"(e.g., Close your month in 2 days, not 12.)\",\n        \"\",\n        \"Subhead – Picture:\",\n        picture || \"(Your CFO sees rollups by Tuesday; your team leaves at 5.)\",\n        \"\",\n        \"Body – Proof:\",\n        (proofBlock || \"(Logos, quantified case study, third-party badges)\"),\n        \"\",\n        \"CTA – Push:\",\n        pushLine || \"(Start your 14-day trial | Book a 20-min fit call this week)\"\n      ]),\n      \"Cold email\": join([\n        \"# Cold email scaffold\",\n        \"Subject:\",\n        promise || \"(State the end benefit clearly.)\",\n        \"\",\n        \"Opening Promise:\",\n        promise || \"(One sentence promise.)\",\n        \"\",\n        \"Picture:\",\n        picture || \"(One sentence painting the new workflow.)\",\n        \"\",\n        \"Proof:\",\n        (lines(proof_metrics).length ? (\"Metric: \" + lines(proof_metrics)[0]) : \"(1 metric)\") + \" \" + (lines(proof_logos).length ? (\"| Peer: \" + lines(proof_logos)[0]) : \"| Peer logo\"),\n        \"\",\n        \"Push:\",\n        pushLine || \"(Propose a specific time, e.g., Thu 2:30 or 4:00.)\"\n      ]),\n      \"Short ad\": join([\n        \"# Short ad scaffold\",\n        \"Promise:\",\n        promise || \"(e.g., Ship AI features 5x faster.)\",\n        \"\",\n        \"Picture:\",\n        picture || \"(Clip or line that shows the result.)\",\n        \"\",\n        \"Proof:\",\n        (lines(proof_metrics).length ? lines(proof_metrics).slice(0,1).join(\", \") : \"Metric or badge\") + (lines(proof_logos).length ? (\" | \" + lines(proof_logos).slice(0,1).join(\", \")) : \"\"),\n        \"\",\n        \"Push:\",\n        push_cta || \"Try free\"\n      ]),\n      \"In-product prompt\": join([\n        \"# In-product prompt scaffold\",\n        \"Promise:\",\n        promise || \"(Outcome tied to current context.)\",\n        \"\",\n        \"Picture:\",\n        picture || \"(One action they will complete next.)\",\n        \"\",\n        \"Proof:\",\n        (lines(proof_metrics).length ? (\"Recent team outcome: \" + lines(proof_metrics)[0]) : \"(Show a timestamped micro-proof)\"),\n        \"\",\n        \"Push:\",\n        pushLine || \"(One button that advances their current task.)\"\n      ])\n    }[channel || \"None\"];\n\n    const qaChecklist = (qa_on === \"Yes\") ? join([\n      \"# QA checklist before you ship\",\n      \"- Promise speaks to a single ICP and a single job.\",\n      \"- Picture shows a before or after moment, not a slogan.\",\n      \"- Proof is specific, recent, and externally verifiable.\",\n      \"- Push is one click or one calendared step; no vague 'learn more'.\",\n      \"- If multiple CTAs exist, remove the extras.\"\n    ]) : null;\n\n    const style = style_notes ? (\"# Style notes\\n\" + style_notes) : null;\n    const legal = compliance ? (\"# Compliance and legal\\n\" + compliance) : null;\n    const track = tracking ? (\"# Tracking plan\\n\" + tracking) : null;\n\n    const modeNote = {\n      \"Outline only\": \"Output mode: outline only.\",\n      \"Table + labels\": \"Output mode: table with labels.\",\n      \"Full working canvas\": \"Output mode: full working canvas with guidance.\"\n    }[output_pref] || \"Output mode: table with labels.\";\n\n    return join([\n      header,\n      \"\",\n      modeNote,\n      \"\",\n      promiseBlock,\n      \"\",\n      pictureBlock,\n      \"\",\n      proofBlock,\n      \"\",\n      pushBlock,\n      \"\",\n      variants,\n      \"\",\n      channelScaffolds,\n      \"\",\n      qaChecklist,\n      \"\",\n      style,\n      \"\",\n      legal,\n      \"\",\n      track,\n      \"\",\n      \"# Tiny templates to swipe\",\n      \"One-liner (homepage hero)\",\n      \"Promise: [Outcome in numbers]\",\n      \"Picture: [Short scene of life after]\",\n      \"Proof: [Metric + logo or badge]\",\n      \"Push: [1 CTA]\",\n      \"\",\n      \"Cold DM email (60 to 80 words)\",\n      \"Promise: \\\"Noticed you [context]. Teams like [peer] cut [pain] by [X percent].\\\"\",\n      \"Picture: \\\"So your [role] gets [desired moment] each [cadence].\\\"\",\n      \"Proof: \\\"Here is a 30 sec clip or case.\\\"\",\n      \"Push: \\\"Worth 15 min Thu.\\\"\"\n    ]);\n  }",
