    "template": "(args = {}) => {\n    const join = function(xs){ return (xs || []).filter(Boolean).join(\"\\n\"); };\n    const lines = function(v){ return String(v || \"\").split(/\\n+/).map(function(s){ return s.trim(); }).filter(Boolean); };\n\n    const {\n      audience_context, goal,\n      motivation_indicators, ability_indicators, route,\n      central_claim, central_numbers, central_reasoning, central_limits, central_sources,\n      peripheral_cues, design_affect, peripheral_cta,\n      scaffold_ability, scaffold_motivation,\n      channel, compliance, win_signals, metrics,\n      output_pref\n    } = args;\n\n    const mode = {\n      \"Outline only\": 1,\n      \"Table + labels\": 2,\n      \"Full working canvas\": 3\n    }[output_pref] || 2;\n\n    const header = join([\n      \"ELM: Elaboration Likelihood Model\",\n      \"One breath: Central route (motivated and able) → strong, issue-relevant arguments that endure. Peripheral route (low motivation and or ability) → simple, trustworthy cues with typically more fragile effects.\",\n      audience_context ? \"Audience and context: \" + audience_context : null,\n      goal ? \"Goal: \" + goal : null,\n      channel ? \"Channel: \" + channel : null\n    ]);\n\n    const diag = join([\n      \"# Diagnose Motivation × Ability\",\n      \"Motivation indicators:\",\n      lines(motivation_indicators).length ? (\"- \" + lines(motivation_indicators).join(\"\\n- \")) : \"(add signals of relevance, stakes, accountability, timing)\",\n      \"\",\n      \"Ability indicators:\",\n      lines(ability_indicators).length ? (\"- \" + lines(ability_indicators).join(\"\\n- \")) : \"(add signals of knowledge, time, attention, distractions)\",\n      \"\",\n      \"Route choice: \" + (route || \"(pick Central, Peripheral, or Scaffold to Central)\")\n    ]);\n\n    const central = join([\n      \"# Central-route pack\",\n      \"Claim:\",\n      central_claim || \"(one strong, issue-relevant claim)\",\n      \"\",\n      \"Evidence (numbers with denominators, methods, uncertainty):\",\n      central_numbers || \"(effect sizes, denominators, confidence intervals, sample size, study design)\",\n      \"\",\n      \"Reasoning and mechanism:\",\n      central_reasoning || \"(how the evidence supports the claim; show mechanisms)\",\n      \"\",\n      \"Counterarguments and limitations:\",\n      central_limits || \"(best objections and scope limits)\",\n      \"\",\n      \"Sources (links to full reports and appendices):\",\n      central_sources || \"(reports, datasets, registered analyses)\",\n      \"\",\n      \"Structure reminder: claim → evidence → reasoning → qualified conclusion.\"\n    ]);\n\n    const peripheral = join([\n      \"# Peripheral-route cues (ethical)\",\n      \"Cues:\",\n      lines(peripheral_cues).length ? (\"- \" + lines(peripheral_cues).join(\"\\n- \")) : \"(credible sources, consensus signals, authority seals, aesthetic fluency, concise stories, mood fit)\",\n      \"\",\n      \"Design and affect:\",\n      design_affect || \"(clarity, readability, accessible visuals, tone that fits the topic)\",\n      \"\",\n      \"Low-effort next step (CTA):\",\n      peripheral_cta || \"(one click or one calendared action)\",\n      \"\",\n      \"Guardrails: keep claims modest; do not overstate; aim to earn attention for future central processing.\"\n    ]);\n\n    const scaffold = join([\n      \"# Scaffold toward Central\",\n      \"Raise ability:\",\n      lines(scaffold_ability).length ? (\"- \" + lines(scaffold_ability).join(\"\\n- \")) : \"(plain language, chunking, glossaries, diagrams, worked examples, progressive disclosure, time to think)\",\n      \"\",\n      \"Raise motivation:\",\n      lines(scaffold_motivation).length ? (\"- \" + lines(scaffold_motivation).join(\"\\n- \")) : \"(personal relevance, goal alignment, immediacy, public commitment, meaningful comparisons)\",\n      \"\",\n      \"Goal: move the audience into a state where central processing is possible and attractive.\"\n    ]);\n\n    const routeBlock = {\n      \"Central\": central,\n      \"Peripheral\": peripheral,\n      \"Scaffold to Central (Mixed)\": join([scaffold, \"\", central]),\n      \"Other\": join([scaffold, \"\", central, \"\", peripheral])\n    }[route || \"Other\"];\n\n    const toolkits = join([\n      \"# Design moves by route\",\n      \"Central toolkit: comparative data; cost benefit logic; replications; mechanism diagrams; calculators; FAQs; counterargument refutation.\",\n      \"Win signals (central): thoughtful questions; note-taking; time-on-page; requests for data.\",\n      \"\",\n      \"Peripheral toolkit: source credibility; consensus signals; aesthetic fluency; authority seals; mnemonic visuals; concise stories; default choices.\",\n      \"Win signals (peripheral): quick compliance; cue-triggered recalls; click-through on one clear CTA.\"\n    ]);\n\n    const traps = join([\n      \"# Common traps and fixes\",\n      \"- Great cues, weak core: fix by strengthening argument quality first.\",\n      \"- Info overload: high ability is not infinite bandwidth. Use hierarchy, summaries, appendices.\",\n      \"- Misattributing routes: the same variable can act as cue or argument depending on elaboration; do not hard-code interpretations.\"\n    ]);\n\n    const measure = join([\n      \"# Measurement\",\n      metrics || \"Track CTR or replies for access; then durable indicators: resistance to counter-message, attitude strength, and behavior follow-through at meaningful intervals.\"\n    ]);\n\n    const ops = join([\n      \"# Compliance and ethics\",\n      compliance || \"Use trustworthy cues; avoid coercion and misleading claims; respect domain regulations (health, finance, policy).\"\n    ]);\n\n    const modeNote = {\n      \"Outline only\": \"Output mode: outline only.\",\n      \"Table + labels\": \"Output mode: table with labels.\",\n      \"Full working canvas\": \"Output mode: full working canvas with guidance.\"\n    }[output_pref] || \"Output mode: table with labels.\";\n\n    return join([\n      header,\n      \"\",\n      modeNote,\n      \"\",\n      diag,\n      \"\",\n      routeBlock,\n      \"\",\n      toolkits,\n      \"\",\n      traps,\n      \"\",\n      measure,\n      \"\",\n      ops\n    ]);\n  }",
