    "template": "(args = {}) => {\n    const join = function(xs){ return (xs || []).filter(Boolean).join(\"\\n\"); };\n    const lines = function(v){ return String(v || \"\").split(/\\n+/).map(function(s){ return s.trim(); }).filter(Boolean); };\n\n    const {\n      decision_scope, audience_context, diagnosis_note,\n      default_plan, menu_structure, comparison_rules, salience_moves, placement_note, exit_path,\n      variant_a, variant_b,\n      qa, metrics, equity_checks, compliance,\n      output_pref\n    } = args;\n\n    const modeNote = {\n      \"Outline only\": \"Output mode: outline only.\",\n      \"Table + labels\": \"Output mode: table with labels.\",\n      \"Full working canvas\": \"Output mode: full working canvas with guidance.\"\n    }[output_pref] || \"Output mode: table with labels.\";\n\n    const header = join([\n      \"Nudge: Ethical Choice Architecture\",\n      \"What it is: structure defaults, ordering, and salience to steer choices while preserving an easy opt out.\",\n      decision_scope ? \"Decision shaped: \" + decision_scope : null,\n      audience_context ? \"Audience and context: \" + audience_context : null,\n      diagnosis_note ? \"Root-cause note (pair with COM-B): \" + diagnosis_note : null,\n      modeNote\n    ]);\n\n    const defaultsBlock = join([\n      \"# Default and opt-out path\",\n      default_plan || \"(Set a pro-user default and describe the reversible path to change it.)\"\n    ]);\n\n    const menuBlock = join([\n      \"# Menu and ordering\",\n      lines(menu_structure).length ? (\"- \" + lines(menu_structure).join(\"\\n- \")) : \"(List options in logical order; limit choices; group meaningfully.)\"\n    ]);\n\n    const compareBlock = join([\n      \"# Comparison standardization\",\n      lines(comparison_rules).length ? (\"- \" + lines(comparison_rules).join(\"\\n- \")) : \"(Show comparable units and totals; include fees, taxes, and overage policies.)\"\n    ]);\n\n    const salienceBlock = join([\n      \"# Salience\",\n      lines(salience_moves).length ? (\"- \" + lines(salience_moves).join(\"\\n- \")) : \"(Highlight total cost, deadlines, and risk near the decision point.)\"\n    ]);\n\n    const placementBlock = join([\n      \"# Placement\",\n      placement_note || \"(Place the helpful action at the exact decision moment where attention already is.)\"\n    ]);\n\n    const exitBlock = join([\n      \"# Exit and confirmation\",\n      exit_path || \"(Make exit easy: one click or one screen; clear confirmation; no traps.)\"\n    ]);\n\n    const variants = join([\n      \"# Test plan (single-lever change)\",\n      \"Variant A (control):\",\n      variant_a || \"(Describe current structure.)\",\n      \"\",\n      \"Variant B (one lever changed):\",\n      variant_b || \"(Describe the single choice-architecture change.)\",\n      \"\",\n      \"Ethics: test for comprehension and downstream outcomes, not clicks alone.\"\n    ]);\n\n    const measure = join([\n      \"# Metrics and window\",\n      metrics || \"Primary outcomes (e.g., correct-plan selection, completion rate). Guardrails (complaints, support tickets). Define a 2–4 week window.\"\n    ]);\n\n    const equity = join([\n      \"# Subgroup and equity checks\",\n      equity_checks || \"Plan cuts by region, device, language, disability settings, new vs returning. Investigate gaps ≥ 5 points.\"\n    ]);\n\n    const policy = compliance ? \"# Compliance and policy\\n\" + compliance : null;\n\n    const qaChecklist = (qa === \"Yes\") ? join([\n      \"# QA and ethics checklist\",\n      \"- Default matches the majority's interest and is reversible in one clear path.\",\n      \"- Menu contains limited, comparable options with standardized totals.\",\n      \"- Salience: totals, deadlines, and risks are prominent and near the choice.\",\n      \"- Placement: the helpful action is at the decision point; no detours.\",\n      \"- Exit: easy opt out; clear confirmation; no obstruction.\",\n      \"- No dark patterns (no forced action, sneaking, or hidden costs).\",\n      \"- Plain language; readability and teach-back tested.\"\n    ]) : null;\n\n    const onePager = join([\n      \"# One-page nudge checklist\",\n      \"Decision: \" + (decision_scope || \"[who, what, where, when]\"),\n      \"Default: \" + (default_plan ? \"set and reversible\" : \"add a pro-user default with easy opt out\"),\n      \"Menu: \" + (lines(menu_structure).length ? \"structured and comparable\" : \"standardize options and units\"),\n      \"Salience: \" + (lines(salience_moves).length ? \"key info highlighted\" : \"highlight totals, risks, deadlines\"),\n      \"Placement: \" + (placement_note || \"[place helpful action at decision point]\"),\n      \"Exit: \" + (exit_path ? \"easy and confirmed\" : \"make exit one click and explicit\"),\n      \"Test: \" + (metrics ? \"metrics defined\" : \"add comprehension and outcome metrics\")\n    ]);\n\n    return join([\n      header,\n      \"\",\n      defaultsBlock,\n      \"\",\n      menuBlock,\n      \"\",\n      compareBlock,\n      \"\",\n      salienceBlock,\n      \"\",\n      placementBlock,\n      \"\",\n      exitBlock,\n      \"\",\n      variants,\n      \"\",\n      measure,\n      \"\",\n      equity,\n      \"\",\n      policy,\n      \"\",\n      qaChecklist,\n      \"\",\n      onePager\n    ]);\n  }",
    "meta": {
      "search_text": "nudge: ethical choice architecture nudge-choice-architecture nudge is the design of choice architecture: structure defaults, ordering, and salience to steer choices in predictable, welfare-enhancing ways while preserving an easy opt out. start from a specific decision (who decides what, where, when). choose a pro-user default with a simple, reversible opt out. make options comparable and the key information salient at the point of decision. place the helpful action where attention already is. test ethically for comprehension and outcomes, monitor subgroup effects, and log the rationale. pair nudge with com-b for root-cause diagnosis, and use east and fogg for friction removal and timing. type:framework use:design use:diagnostic use:copywriting use:experimentation use:onboarding use:policy-communications topic:nudge topic:choice-architecture topic:defaults topic:salience topic:menus phase:discovery phase:activation phase:scale level:beginner mode:analysis mode:writing persona:user-experience-writer persona:user-experience-designer persona:product-manager persona:growth-product-manager persona:service-designer persona:operations-leader persona:policy-analyst persona:program-manager persona:compliance-officer persona:privacy-officer scope:self scope:pair scope:team scope:organization scope:community scope:society lens:secular lens:western analysis strategy product design marketing communications public-policy service-design decision shaped (who, what, where, when) audience and context root-cause note (pair with com-b) default setting (with opt-out path) menu structure (options, order, grouping) comparison standardization salience moves placement note exit and confirmation variant a (control) variant b (single lever change) qa checklist on output metrics and window subgroup and equity checks compliance and policy notes output preference"
    }
