    "template": "(args = {}) => {\n    const join = function(xs){ return (xs || []).filter(Boolean).join(\"\\n\"); };\n    const lines = function(v){ return String(v || \"\").split(/\\n+/).map(function(s){ return s.trim(); }).filter(Boolean); };\n\n    const {\n      audience_context, goal,\n      target_type, threat_line,\n      tactics, weakened_examples, refutation_rules,\n      format, channels, timing,\n      localization, ethics,\n      evaluation, metrics, cta,\n      output_pref\n    } = args;\n\n    const mode = {\n      \"Outline only\": \"Output mode: outline only.\",\n      \"Table + labels\": \"Output mode: table with labels.\",\n      \"Full working canvas\": \"Output mode: full working canvas with guidance.\"\n    }[output_pref] || \"Output mode: table with labels.\";\n\n    const header = join([\n      \"Inoculation Theory & Prebunking\",\n      \"Idea: expose a weakened counterargument plus refutation before real exposure to build resistance; teach manipulation techniques so skills transfer.\",\n      audience_context ? \"Audience and context: \" + audience_context : null,\n      goal ? \"Goal: \" + goal : null,\n      \"Style: \" + (target_type || \"(choose classic inoculation, technique-based prebunking, or mixed)\"),\n      mode\n    ]);\n\n    const forewarn = join([\n      \"# Threat and forewarning\",\n      threat_line || \"(Write one sentence: You will likely see posts that use [tactic]. This raises defense motivation.)\"\n    ]);\n\n    const tacticBlock = join([\n      \"# Tactics to cover\",\n      lines(tactics).length ? (\"- \" + lines(tactics).join(\"\\n- \")) : \"(List named techniques with one-line tells, e.g., scapegoating, false dichotomy, whataboutism, decontextualization.)\"\n    ]);\n\n    const weakenedBlock = join([\n      \"# Weakened examples\",\n      lines(weakened_examples).length ? (\"- \" + lines(weakened_examples).join(\"\\n- \")) : \"(Draft short, realistic examples that demonstrate the tactic without full strength.)\"\n    ]);\n\n    const refuteBlock = join([\n      \"# Refutation rules (keep cognitive cost low)\",\n      lines(refutation_rules).length ? (\"- \" + lines(refutation_rules).join(\"\\n- \")) : \"(Provide two-step checks users can perform in under 10 seconds.)\",\n      cta ? \"Recall cue: \" + cta : null\n    ]);\n\n    const formatBlock = join([\n      \"# Format and channels\",\n      \"Format: \" + (format || \"(90-second video, interactive mini-game, in-app card, print sidebar, short course)\"),\n      \"Channels:\",\n      lines(channels).length ? (\"- \" + lines(channels).join(\"\\n- \")) : \"(List distribution surfaces: short-video, pre-roll, SMS, print, in-product.)\"\n    ]);\n\n    const timingBlock = join([\n      \"# Timing and boosters\",\n      timing || \"Place prebunks before predictable spikes and schedule boosters 2–6 weeks later; effects decay without refresh.\"\n    ]);\n\n    const localizationBlock = join([\n      \"# Localization and messenger\",\n      localization || \"Tailor examples, language, and messengers to locale; bespoke creatives beat generic dubbing.\"\n    ]);\n\n    const ethicsBlock = join([\n      \"# Ethics and safety\",\n      ethics || \"Be transparent about intent, avoid stigmatizing groups, and provide support resources. Do not fear-prime without tools.\"\n    ]);\n\n    const evalBlock = join([\n      \"# Evaluation and metrics\",\n      evaluation || \"Use pre/post recognition quizzes, share-intention tasks, randomized holdouts, and follow-ups for decay and booster gains.\",\n      \"\",\n      \"Metrics:\",\n      metrics || \"Primary: technique recognition and reduced share-intent. Guardrails: complaints, accuracy confidence. Downstream: spread of flagged patterns.\"\n    ]);\n\n    const worksheet = join([\n      \"# One-page prebunking worksheet (copy)\",\n      \"Threat: \" + (threat_line || \"You may soon see posts using [tactic].\"),\n      \"Tactic and tell: \" + (lines(tactics)[0] || \"[name the technique + how to spot it]\"),\n      \"Weakened example: \" + (lines(weakened_examples)[0] || \"[short realistic clip or text]\"),\n      \"Refutation rule: \" + (lines(refutation_rules)[0] || \"[2-step check in under 10 seconds]\"),\n      \"Format: \" + (format || \"[video/game/print/card]\"),\n      \"Timing: \" + (timing || \"[run before event; booster in 2–4 weeks]\"),\n      \"Measure: \" + (metrics || \"[recognition, share-intent, downstream spread; segment by locale]\")\n    ]);\n\n    return join([\n      header,\n      \"\",\n      forewarn,\n      \"\",\n      tacticBlock,\n      \"\",\n      weakenedBlock,\n      \"\",\n      refuteBlock,\n      \"\",\n      formatBlock,\n      \"\",\n      timingBlock,\n      \"\",\n      localizationBlock,\n      \"\",\n      ethicsBlock,\n      \"\",\n      evalBlock,\n      \"\",\n      worksheet\n    ]);\n  }",
