    "template": "(args = {}) => {\n    const join = function(xs){ return (xs || []).filter(Boolean).join(\"\\n\"); };\n    const lines = function(v){ return String(v || \"\").split(/\\n+/).map(function(s){ return s.trim(); }).filter(Boolean); };\n\n    const {\n      decision_metric, audience_context, reference_point,\n      behavior_class, frame_choice,\n      absolute_facts, gain_copy, loss_copy, probability_notes,\n      pricing_context, test_plan, metrics, ethics, notes,\n      output_pref\n    } = args;\n\n    const mode = {\n      \"Outline only\": \"Output mode: outline only.\",\n      \"Table + labels\": \"Output mode: table with labels.\",\n      \"Full working canvas\": \"Output mode: full working canvas with guidance.\"\n    }[output_pref] || \"Output mode: table with labels.\";\n\n    const header = join([\n      \"Prospect Theory: Reference Points, Framing, and Loss Aversion\",\n      \"Idea: people judge outcomes as gains or losses relative to a reference point; losses often loom larger; framing shifts the reference.\",\n      decision_metric ? \"Decision and metric: \" + decision_metric : null,\n      audience_context ? \"Audience and context: \" + audience_context : null,\n      reference_point ? \"Reference point: \" + reference_point : \"Reference point: (status quo, expectation, goal, or peer norm)\",\n      \"Behavior class: \" + (behavior_class || \"(prevention, detection, conversion, retention, comprehension)\"),\n      \"Frame: \" + (frame_choice || \"(gain, loss, or both)\"),\n      mode\n    ]);\n\n    const mechanics = join([\n      \"# Key mechanics to honor\",\n      \"- Reference dependence: change the reference, change the choice.\",\n      \"- Loss aversion and endowment: expect higher willingness-to-accept to give up than willingness-to-pay to get.\",\n      \"- Probability weighting: avoid lottery framing of tiny chances; use absolute frequencies.\",\n      \"- Framing types: risky-choice, attribute, and goal framing.\"\n    ]);\n\n    const factsBlock = join([\n      \"# Facts (absolute numbers; identical denominators)\",\n      lines(absolute_facts).length ? (\"- \" + lines(absolute_facts).join(\"\\n- \")) : \"(Write facts as frequencies, e.g., 2 out of 100, not 2 percent.)\"\n    ]);\n\n    const copyBlock = join([\n      \"# Framing copy (hold facts constant)\",\n      \"Gain frame:\",\n      gain_copy || \"(Write the benefit framing using the same facts.)\",\n      \"\",\n      \"Loss frame:\",\n      loss_copy || \"(Write the loss framing using the same facts.)\"\n    ]);\n\n    var frameHint = null;\n    var bc = String(behavior_class || \"\").toLowerCase();\n    if (bc) {\n      var map = {\n        \"prevention behavior\": \"Hint: prevention behaviors tend to respond better to gain frames; still validate with your audience.\",\n        \"detection/screening\": \"Hint: detection or screening can benefit from careful loss framing plus absolute risk tables.\",\n        \"conversion (acquisition)\": \"Hint: for acquisition, set a clear reference price and emphasize gains; avoid fear-heavy loss framing.\",\n        \"retention (avoid churn)\": \"Hint: for retention, highlight losses from switching with concrete forfeits and migration costs.\",\n        \"comprehension/education\": \"Hint: show both frames side-by-side with identical denominators; measure understanding.\"\n      };\n      frameHint = map[bc] || null;\n    }\n\n    var bothNote = null;\n    if (String(frame_choice || \"\").toLowerCase() === \"both\") {\n      bothNote = \"Dual-frame plan: present gain and loss versions side-by-side with identical denominators and placement.\";\n    }\n\n    const probBlock = join([\n      \"# Probability presentation\",\n      probability_notes || \"Rewrite percents to frequencies (e.g., 1 in 1,000). Avoid sensational language for rare events.\"\n    ]);\n\n    var pricingNote = null;\n    var pc = String(pricing_context || \"\").toLowerCase();\n    if (pc) {\n      var pmap = {\n        \"acquisition\": \"Pricing note (acquisition): use trials and reference resets; avoid overplaying losses which can backfire.\",\n        \"retention\": \"Pricing note (retention): show concrete forfeits, relearning time, and switching costs; endowment effects favor incumbents.\",\n        \"both\": \"Pricing note: acquisition needs reference resets and gain framing; retention can responsibly highlight losses from switching.\"\n      };\n      pricingNote = pmap[pc] || null;\n    }\n\n    const testBlock = join([\n      \"# Test design\",\n      test_plan || \"A B test where only the frame changes. Keep facts, denominators, visuals, and placement identical. Run long enough to detect modest effects.\",\n      \"\",\n      \"Metrics and guardrails:\",\n      metrics || \"Primary: choice quality (correct plan, correct risk understanding). Guardrails: complaint rate, support volume, time-on-task.\"\n    ]);\n\n    const ethicsBlock = join([\n      \"# Ethics and assumptions\",\n      ethics || \"Disclose assumptions and baselines; avoid fear inflation; show both yearly and per-period numbers; check subgroup effects.\"\n    ]);\n\n    const notesBlock = notes ? \"# Notes\\n\" + notes : null;\n\n    const planner = join([\n      \"# One-page framing planner (copy)\",\n      \"Decision & metric: \" + (decision_metric || \"[conversion | adherence | comprehension]\"),\n      \"Audience & context: \" + (audience_context || \"[who, where]\"),\n      \"Reference point: \" + (reference_point || \"[status quo | expectation | goal | peer norm]\"),\n      \"Frame: \" + (frame_choice || \"[gain | loss | both]\"),\n      \"Copy seeds:\",\n      \"- Gain: \" + (gain_copy || \"[benefit wording using identical facts]\"),\n      \"- Loss: \" + (loss_copy || \"[cost wording using identical facts]\"),\n      \"Risks & probabilities: \" + (probability_notes || \"[use absolute frequencies; avoid lottery framing]\"),\n      \"Test: \" + (test_plan || \"[A/B with facts constant; track choice quality]\"),\n      \"Guardrails: \" + (metrics || \"[define primary and safety metrics]\")\n    ]);\n\n    return join([\n      header,\n      \"\",\n      mechanics,\n      \"\",\n      factsBlock,\n      \"\",\n      copyBlock,\n      \"\",\n      frameHint,\n      bothNote,\n      \"\",\n      probBlock,\n      \"\",\n      pricingNote,\n      \"\",\n      testBlock,\n      \"\",\n      ethicsBlock,\n      \"\",\n      notesBlock,\n      \"\",\n      planner\n    ]);\n  }",
