    "template": "(args = {}) => {\n    const join = function(xs){ return (xs || []).filter(Boolean).join(\"\\n\"); };\n    const lines = function(v){ return String(v || \"\").split(/\\n+/).map(function(s){ return s.trim(); }).filter(Boolean); };\n\n    const {\n      title, audience_goal,\n      format, tone, length_pref, timebox,\n      act3_decision, act3_metric, act3_new_normal,\n      act1_world, act1_goal, act1_incident, act1_pnr,\n      act2_complications, act2_midpoint, act2_darkest, act2_insight,\n      receipts_a1, receipts_a2, receipts_a3,\n      qa, output_pref\n    } = args;\n\n    const modeNote = {\n      \"Outline only\": \"Output mode: outline only.\",\n      \"Table + labels\": \"Output mode: table with labels.\",\n      \"Full working canvas\": \"Output mode: full working canvas with guidance.\"\n    }[output_pref] || \"Output mode: table with labels.\";\n\n    const header = join([\n      \"3-Act Structure — Setup → Confrontation → Resolution\",\n      title ? \"Title: \" + title : null,\n      audience_goal ? \"Audience and goal: \" + audience_goal : null,\n      format ? \"Format: \" + format : null,\n      tone && tone !== \"None\" ? \"Tone: \" + tone : null,\n      \"Timebox targets (A1/A2/A3): \" + (timebox || \"10/70/20\"),\n      modeNote\n    ]);\n\n    const act3First = join([\n      \"# Start with the climax\",\n      \"Decision: \" + (act3_decision || \"(name the decisive action at the climax)\"),\n      \"Payoff metric: \" + (act3_metric || \"(the number that proves payoff)\"),\n      \"New normal: \" + (act3_new_normal || \"(what changed and what it cost)\")\n    ]);\n\n    const act1 = join([\n      \"# Act 1 — Setup\",\n      \"World and status quo: \" + (act1_world || \"(baseline reality)\"),\n      \"Protagonist and goal: \" + (act1_goal || \"(who wants what and why now)\"),\n      \"Inciting incident: \" + (act1_incident || \"(event that forces action)\"),\n      \"Point of no return: \" + (act1_pnr || \"(commitment that breaks the old pattern)\"),\n      \"\",\n      \"Receipts (Act 1):\",\n      lines(receipts_a1).length ? (\"- \" + lines(receipts_a1).join(\"\\n- \")) : \"- (add one chart or concrete example)\"\n    ]);\n\n    const comps = lines(act2_complications);\n    const act2 = join([\n      \"# Act 2 — Confrontation\",\n      \"Rising complications:\",\n      comps.length ? (\"- \" + comps.join(\"\\n- \")) : \"- (list trials, surprises, constraints)\",\n      \"Midpoint reversal: \" + (act2_midpoint || \"(the flip that reframes stakes)\"),\n      \"Darkest moment: \" + (act2_darkest || \"(where the old plan fails visibly)\"),\n      \"Insight or new plan: \" + (act2_insight || \"(lesson that enables Act 3)\"),\n      \"\",\n      \"Receipts (Act 2):\",\n      lines(receipts_a2).length ? (\"- \" + lines(receipts_a2).join(\"\\n- \")) : \"- (add one chart or concrete example)\"\n    ]);\n\n    const act3 = join([\n      \"# Act 3 — Resolution\",\n      \"Decisive action: \" + (act3_decision || \"(state again for clarity)\"),\n      \"Payoff metric: \" + (act3_metric || \"(the number to check)\"),\n      \"New normal: \" + (act3_new_normal || \"(show life after)\"),\n      \"\",\n      \"Receipts (Act 3):\",\n      lines(receipts_a3).length ? (\"- \" + lines(receipts_a3).join(\"\\n- \")) : \"- (add one chart or concrete example)\"\n    ]);\n\n    const storyboard = join([\n      \"# Nine-card storyboard (three per act)\",\n      \"Act 1 — Setup: \" + (act1_world || \"(world/status quo)\"),\n      \"Act 1 — Turn: \" + (act1_incident || \"(inciting incident)\"),\n      \"Act 1 — Consequence: \" + (act1_pnr || \"(point of no return)\"),\n      \"Act 2 — Setup: \" + (comps[0] || \"(first complication)\"),\n      \"Act 2 — Turn: \" + (act2_midpoint || \"(midpoint reversal)\"),\n      \"Act 2 — Consequence: \" + (act2_darkest || \"(darkest moment)\"),\n      \"Act 3 — Setup: \" + (act2_insight || \"(insight or new plan)\"),\n      \"Act 3 — Turn: \" + (act3_decision || \"(decisive action)\"),\n      \"Act 3 — Consequence: \" + (act3_new_normal || \"(new normal)\")\n    ]);\n\n    const microPrompts = join([\n      \"# Micro-prompts\",\n      \"- Act 1: who wants what, why now, and what kicks this off.\",\n      \"- Act 2: what fails, what is learned, and what flips at the midpoint.\",\n      \"- Act 3: what choice is made, what changes, and what lesson remains.\"\n    ]);\n\n    const quality = join([\n      \"# Quality checks\",\n      \"- Midpoint present: can you point to a perspective flip?\",\n      \"- Darkest moment named: is there a visible failure before payoff?\",\n      \"- New normal shown: do we see life after, not just the decision?\",\n      \"- Scene economy: remove beats that neither raise stakes nor change knowledge.\"\n    ]);\n\n    const qaBlock = (qa === \"Yes\") ? join([\n      \"# QA checklist\",\n      \"- Meandering Act 2? Anchor it on the midpoint reversal.\",\n      \"- Instant resolution? Insert cost or tradeoff before payoff.\",\n      \"- Lore dump in Act 1? Keep context to one page or slide.\",\n      \"- Missing coda? Add a short metric or cultural change to show the new normal.\"\n    ]) : null;\n\n    const pairings = join([\n      \"# Useful pairings\",\n      \"- ABT for the one-sentence logline; expand each clause into an act.\",\n      \"- ELM HSM: central reasoning in Act 2; credible cues in Acts 1 and 3.\",\n      \"- EAST: make the Act 3 ask Easy, Attractive, Social, and Timely.\"\n    ]);\n\n    const lengthNote = length_pref && length_pref !== \"None\" ? \"Length preference: \" + length_pref + \".\" : null;\n\n    return join([\n      header,\n      \"\",\n      act3First,\n      \"\",\n      act1,\n      \"\",\n      act2,\n      \"\",\n      act3,\n      \"\",\n      storyboard,\n      \"\",\n      microPrompts,\n      \"\",\n      quality,\n      \"\",\n      qaBlock,\n      \"\",\n      pairings,\n      \"\",\n      lengthNote\n    ]);\n  }",
