    "template": "(args = {}) => {\n    const join = function(xs){ return (xs || []).filter(Boolean).join(\"\\n\"); };\n    const lines = function(v){ return String(v || \"\").split(/\\n+/).map(function(s){ return s.trim(); }).filter(Boolean); };\n\n    const {\n      context, claim, counter,\n      def_claim, def_counter,\n      cmp_claim, cmp_counter,\n      deg_claim, deg_counter,\n      rel_claim, rel_counter,\n      cir_claim, cir_counter,\n      tes_claim, tes_counter,\n      sources,\n      stitch, format, tone, length_pref, qa\n    } = args;\n\n    const header = join([\n      \"Topoi (Common Topics) — Claim vs Counter\",\n      context ? \"Context: \" + context : null,\n      claim ? \"Claim: \" + claim : \"Claim: [one sentence thesis]\",\n      counter ? \"Counter-claim: \" + counter : \"Counter-claim: [steelman the opposing thesis]\",\n      tone && tone !== \"None\" ? \"Tone: \" + tone : null,\n      \"Output: \" + ((format && format !== \"None\") ? format : \"Table\") + \" — \" + ((length_pref && length_pref !== \"None\") ? length_pref : \"Table + bullets\")\n    ]);\n\n    const table = join([\n      \"# Topoi sweep\",\n      \"| Topic | Claim answers | Counter answers |\",\n      \"| --- | --- | --- |\",\n      \"| Definition | \" + (def_claim || \"Genus/differentia, parts/whole, necessary/sufficient.\") + \" | \" + (def_counter || \"Opposing definition or classification.\") + \" |\",\n      \"| Comparison | \" + (cmp_claim || \"Nearest analogs and where the analogy breaks.\") + \" | \" + (cmp_counter || \"Opposing analogs and breaks.\") + \" |\",\n      \"| Degree | \" + (deg_claim || \"More/less, thresholds, diminishing returns.\") + \" | \" + (deg_counter || \"Opposing tradeoffs and thresholds.\") + \" |\",\n      \"| Relationship | \" + (rel_claim || \"Cause/effect, consequences, confounds.\") + \" | \" + (rel_counter || \"Opposing causal chain and confounds.\") + \" |\",\n      \"| Circumstances | \" + (cir_claim || \"Feasibility, timing, constraints, precedent.\") + \" | \" + (cir_counter || \"Opposing feasibility read or constraint risk.\") + \" |\",\n      \"| Testimony | \" + (tes_claim || \"Data, cases, expert consensus with recency.\") + \" | \" + (tes_counter || \"Counter-sources, alternative cases.\") + \" |\"\n    ]);\n\n    const sourcesBlock = join([\n      \"# Evidence planner\",\n      lines(sources).length ? (\"- \" + lines(sources).join(\"\\n- \")) : \"- (List datasets, logs, cases, expert sources, and who will gather them)\"\n    ]);\n\n    const converge = join([\n      \"# Converge and stitch\",\n      \"Select the few proofs that are relevant, credible, and feasible. Then stitch into: \" + (stitch || \"PSP or ABT\") + \".\",\n      \"Suggested mapping:\",\n      \"- Definition and Comparison → background and positioning.\",\n      \"- Relationship and Degree → core argument and tradeoffs.\",\n      \"- Circumstances and Testimony → feasibility and proof.\"\n    ]);\n\n    const qaBlock = (qa === \"Yes\") ? join([\n      \"# QA checks\",\n      \"- Empty topic: if a topos has no content, research or narrow scope.\",\n      \"- Confirmation bias: counter column must be filled for at least three topics.\",\n      \"- Testimony quality: prefer replicated, recent, and domain-relevant sources.\",\n      \"- Causality: check for confounds, reversals, and post-hoc stories under Relationship.\",\n      \"- Feasibility: confirm constraints, timing, and precedent under Circumstances.\"\n    ]) : null;\n\n    const quickWorksheet = join([\n      \"# Fast worksheet\",\n      \"Claim: \" + (claim || \"…\"),\n      \"Definition: \" + (def_claim || \"best label, criteria, boundaries\"),\n      \"Comparison: \" + (cmp_claim || \"nearest analogs; where the analogy breaks\"),\n      \"Degree: \" + (deg_claim || \"more/less tradeoffs; thresholds\"),\n      \"Relationship: \" + (rel_claim || \"causal chain; side effects; reversals\"),\n      \"Circumstances: \" + (cir_claim || \"feasibility; timing; precedent; constraints\"),\n      \"Testimony: \" + (tes_claim || \"data; cases; expert consensus; counter-evidence\"),\n      \"Counter-case highlights: \" + (def_counter || cmp_counter || deg_counter || rel_counter || cir_counter || tes_counter || \"…\"),\n      \"Decision: \" + \"[what follows and why]\"\n    ]);\n\n    return join([\n      header,\n      \"\",\n      table,\n      \"\",\n      sourcesBlock,\n      \"\",\n      converge,\n      \"\",\n      qaBlock,\n      \"\",\n      quickWorksheet\n    ]);\n  }",
