    "template": "(args = {}) => {\n    const join = function(xs){ return (xs || []).filter(Boolean).join(\"\\n\"); };\n    const lines = function(v){ return String(v || \"\").split(/\\n+/).map(function(s){ return s.trim().replace(/[.?!]\\s*$/,\"\"); }).filter(Boolean); };\n    const a = args || {};\n\n    const header = join([\n      \"Anaphora — Repeat Openers For Rhythm And Clarity\",\n      a.title ? \"Title: \" + a.title : null,\n      a.context && a.context !== \"None\" ? \"Context: \" + a.context : null,\n      a.audience ? \"Audience: \" + a.audience : null\n    ]);\n\n    const anchor = (a.anchor || \"\").trim();\n    const beatsRaw = lines(a.beats).slice(0, 3);\n    const triad = anchor ? beatsRaw.map(function(b){ return anchor + \" \" + b + \".\"; }) : [];\n    const counts = beatsRaw.map(function(s){ return s.length; });\n    const lenNote = counts.length === 3 ? (\"Length balance: min \" + Math.min(counts[0], counts[1], counts[2]) + \" chars, max \" + Math.max(counts[0], counts[1], counts[2]) + \" chars — aim for similar rhythm.\") : null;\n\n    const messy = lines(a.raw_series);\n    const refactor = (function(){\n      if (!anchor || !messy.length){ return null; }\n      var three = messy.slice(0, 3).map(function(s){ return anchor + \" \" + s + \".\"; });\n      return join([\n        \"Before:\",\n        \"- \" + messy.join(\"\\n- \"),\n        \"After:\",\n        \"- \" + three.join(\"\\n- \")\n      ]);\n    })();\n\n    const styleNote = (function(){\n      if (a.style === \"Isocolon (equal rhythm)\"){ return \"Style: Isocolon — keep each clause near-equal length for snap.\"; }\n      if (a.style === \"Epistrophe (repeat at end)\"){ return \"Style: Epistrophe — repeat a closing word for echo (use sparingly with anaphora).\"; }\n      if (a.style === \"Symploce (repeat at start and end)\"){ return \"Style: Symploce — repeat at both start and end to bracket the point.\"; }\n      if (a.style === \"Anadiplosis (linking end→start)\"){ return \"Style: Anadiplosis — end one clause with a word that begins the next; weave lightly.\"; }\n      if (a.style === \"Other\"){ return \"Style: Custom — ensure clarity precedes flourish.\"; }\n      return null;\n    })();\n\n    const rationale = join([\n      \"# Why it works\",\n      \"- Cueing memory: repetition pins the theme to the start of each clause.\",\n      \"- Processing ease: stable openings speed parsing and reduce cognitive load.\",\n      \"- Percussive rhythm: matched starts create momentum and signal importance.\"\n    ]);\n\n    const how = join([\n      \"# How to use it well\",\n      \"- Choose one anchor phrase; keep words and tense identical.\",\n      \"- Aim for three beats; triads are memorable.\",\n      \"- Make continuations parallel; align part of speech and structure.\",\n      \"- Escalate meaning across beats; end with a payoff line.\",\n      \"- Stop at three unless more truly earns its keep.\"\n    ]);\n\n    const micros = join([\n      \"# Micro-templates\",\n      \"- Policy: \\\"We will … We will … We will …\\\" → end with how you will measure.\",\n      \"- Research: \\\"We observed … We controlled for … We confirmed …\\\" → give the effect size.\",\n      \"- Product: \\\"You connect … You configure … You launch …\\\" → show time to value.\",\n      \"- Values: \\\"Build openly. Build securely. Build for scale.\\\" → link to the playbook.\"\n    ]);\n\n    const qc = a.append_qc === \"Yes\" ? join([\n      \"# Quality checklist\",\n      \"- Same opener, same tense, same person.\",\n      \"- Parallel grammar after the opener.\",\n      \"- Escalation or progression across beats.\",\n      \"- Clear payoff sentence after the series.\",\n      \"- No padding; the opener should not change meaning.\"\n    ]) : null;\n\n    const seriesBlock = join([\n      \"# Series\",\n      triad.length ? (\"- \" + triad.join(\"\\n- \")) : \"- (set Anchor phrase and Beats to render the triad)\",\n      lenNote,\n      a.payoff ? \"Payoff: \" + a.payoff : null\n    ]);\n\n    const outputNote = (function(){\n      var mode = a.output_pref || \"Series + rationale\";\n      if (mode === \"Series only\"){ return \"Output: series only.\"; }\n      if (mode === \"Series + rationale\"){ return \"Output: series plus rationale.\"; }\n      if (mode === \"Full worksheet\"){ return \"Output: full worksheet.\"; }\n      if (mode === \"Other\"){ return \"Output: custom.\"; }\n      return \"Output: series plus rationale.\";\n    })();\n\n    return join([\n      header,\n      \"\",\n      outputNote,\n      \"\",\n      seriesBlock,\n      \"\",\n      a.output_pref === \"Series only\" ? null : join([rationale, \"\", how, \"\", micros]),\n      \"\",\n      styleNote,\n      \"\",\n      \"# Before → After\",\n      refactor || \"- (add an Anchor and Raw messy series to see a refactor)\",\n      \"\",\n      qc\n    ]);\n  }",
    "meta": {
      "search_text": "anaphora — repeat openers for rhythm and clarity anaphora a rhetorical scaffold that repeats the same opening word or phrase across successive clauses to build clarity, rhythm, and force, typically in a memorable triad with a closing payoff line. pick a short anchor phrase the audience can predict (e.g., “we will”, “you can”, “our data show”). write three simple beats (one per line) that continue the anchor in parallel grammar. escalate meaning across beats, then add a payoff sentence that concludes or decides. use for policies, onboarding, research summaries, team principles, and public remarks. keep the opener identical in wording and tense; stop at three unless more truly earns its keep. type:framework use:editing use:microcopy use:messaging use:speechwriting use:slides use:docs topic:anaphora topic:rhetoric topic:parallelism topic:style phase:delivery phase:revision level:beginner mode:writing persona:user-experience-writer persona:content-designer persona:product-manager persona:product-marketer persona:technical-writer persona:developer-advocate persona:researcher persona:educator persona:policy-analyst persona:journalist persona:executive scope:self scope:pair scope:team scope:organization scope:community scope:society lens:secular lens:western writing communications marketing product design research education policy title context audience anchor phrase (repeated opener) beats (3 lines, no periods) payoff line (conclusion/decision) tense person style variant raw messy series (optional) output preference append quality checklist"
    }
