    "template": "(args = {}) => {\n    const join = function(xs){ return (xs || []).filter(Boolean).join(\"\\n\"); };\n    const lines = function(v){ return String(v || \"\").split(/\\n+/).map(function(s){ return s.trim(); }).filter(Boolean); };\n    const a = args || {};\n\n    const header = join([\n      \"Antithesis — Sharpen The Choice With Parallel Opposites\",\n      a.title ? \"Title: \" + a.title : null,\n      a.context && a.context !== \"None\" ? \"Context: \" + a.context : null,\n      a.audience ? \"Audience: \" + a.audience : null\n    ]);\n\n    const pattern = a.pattern || \"Not X, but Y\";\n    const X = (a.x_axis || \"\").trim();\n    const Y = (a.y_axis || \"\").trim();\n    const A = (a.conseq_a || \"\").trim();\n    const B = (a.conseq_b || \"\").trim();\n    const EX = (a.evidence_x || \"\").trim();\n    const EY = (a.evidence_y || \"\").trim();\n\n    const baseLine = (function(){\n      if (!X || !Y){ return \"- (add Axis X and Axis Y)\"; }\n      if (pattern === \"Not X, but Y\"){ return \"Not \" + X + \", but \" + Y + \".\"; }\n      if (pattern === \"X invites A; Y invites B\"){\n        var left = X + (A ? \" invites \" + A : \"\");\n        var right = Y + (B ? \" invites \" + B : \"\");\n        return left + \"; \" + right + \".\";\n      }\n      if (pattern === \"From X to Y\"){ return \"From \" + X + \" to \" + Y + \".\"; }\n      if (pattern === \"Choose X over Y\"){ return \"Choose \" + Y + \" over \" + X + \".\"; }\n      return X + \" vs \" + Y + \".\";\n    })();\n\n    const symmetryNote = (function(){\n      var lx = X.length, ly = Y.length;\n      if (!lx || !ly){ return null; }\n      var diff = Math.abs(lx - ly);\n      var max = Math.max(lx, ly);\n      var pct = max ? Math.round((diff / max) * 100) : 0;\n      return \"Symmetry check: X=\" + lx + \" chars, Y=\" + ly + \" chars (Δ≈\" + pct + \"%). Aim for similar length and matching grammar.\";\n    })();\n\n    const consequences = (function(){\n      if (!A && !B){ return null; }\n      return join([\n        \"# Consequences\",\n        A ? \"- \" + X + \" → \" + A : null,\n        B ? \"- \" + Y + \" → \" + B : null\n      ]);\n    })();\n\n    const evidence = (function(){\n      if (!EX && !EY){ return null; }\n      return join([\n        \"# Evidence\",\n        EX ? \"- For \" + X + \": \" + EX : null,\n        EY ? \"- For \" + Y + \": \" + EY : null\n      ]);\n    })();\n\n    const middle = a.middle_note ? (\"Middle path note: \" + a.middle_note) : null;\n\n    const styleNote = (function(){\n      if (a.style === \"Antimetabole\"){ return \"Style: Antimetabole — reverse the order, e.g., “We shape our tools; our tools shape us.”\"; }\n      if (a.style === \"Chiasmus\"){ return \"Style: Chiasmus — ABBA balance: “Control the process, and the process will control you.”\"; }\n      if (a.style === \"Concessive turn\"){ return \"Style: Concessive — “X is attractive, yet Y is wiser.”\"; }\n      if (a.style === \"Isocolon\"){ return \"Style: Isocolon — keep clauses equal in length for snap: “Less process. More progress.”\"; }\n      if (a.style === \"Other\"){ return \"Style: Custom — add flourish only after clarity and honesty.\"; }\n      return null;\n    })();\n\n    const decision = a.decision ? (\"Decision: \" + a.decision) : null;\n    const mitigations = lines(a.mitigations).length ? join([\"Mitigations:\", \"- \" + lines(a.mitigations).join(\"\\n- \")]) : null;\n\n    const messy = lines(a.raw);\n    const refactor = (function(){\n      if (!messy.length || !X || !Y){ return null; }\n      return join([\n        \"Before:\",\n        \"- \" + messy.join(\"\\n- \"),\n        \"After:\",\n        \"- Not \" + X + \", but \" + Y + \".\"\n      ]);\n    })();\n\n    const qc = a.append_qc === \"Yes\" ? join([\n      \"# Quality checklist\",\n      \"- Single axis only; no kitchen-sink contrasts.\",\n      \"- Parallel grammar and roughly similar length on both sides.\",\n      \"- Each half ties to a concrete consequence.\",\n      \"- At least one evidence point per side (or state that evidence is pending).\",\n      \"- Avoid false dichotomy; include middle-path note if a spectrum exists.\"\n    ]) : null;\n\n    const rationale = join([\n      \"# Why it works\",\n      \"- Contrast focuses attention; side-by-side opposites reduce interpretation time.\",\n      \"- Parallelism aids memory; matched grammar creates rhythm.\",\n      \"- Decision forcing; a clean antithesis makes dithering feel costly.\"\n    ]);\n\n    const how = join([\n      \"# How to craft crisp antithesis\",\n      \"- Pick one axis (e.g., speed vs certainty).\",\n      \"- Write the Y you want first; then define X as its foil.\",\n      \"- Keep halves parallel in part of speech, tense, and length.\",\n      \"- Tie each half to a consequence (invites/avoids/produces).\",\n      \"- Prefer concrete nouns and active verbs.\"\n    ]);\n\n    const outputFlag = a.output_pref || \"Full worksheet\";\n    const seriesOnly = outputFlag === \"Line only\";\n    const seriesPlus = outputFlag === \"Line + consequences\";\n\n    return join([\n      header,\n      \"\",\n      \"# Antithesis line\",\n      baseLine,\n      symmetryNote,\n      \"\",\n      seriesOnly ? null : consequences,\n      seriesOnly ? null : evidence,\n      seriesOnly ? null : middle,\n      \"\",\n      decision,\n      mitigations,\n      \"\",\n      seriesPlus || seriesOnly ? null : rationale,\n      seriesPlus || seriesOnly ? null : \"\",\n      seriesPlus || seriesOnly ? null : how,\n      \"\",\n      \"# Before → After\",\n      refactor || \"- (add Axis X, Axis Y, and a Raw sentence to see a refactor)\",\n      \"\",\n      qc\n    ]);\n  }",
