    "template": "(args = {}) => {\n    var a = args || {};\n    function join(xs){ return (xs || []).filter(Boolean).join(\"\\n\"); }\n    function sameToken(x){ return String(x || \"\").trim(); }\n\n    var title = sameToken(a.title);\n    var context = a.context && a.context !== \"None\" ? a.context : \"\";\n    var audience = sameToken(a.audience);\n\n    var A = sameToken(a.token_a);\n    var B = sameToken(a.token_b);\n    var link1 = sameToken(a.link1) || \"to\";\n    var link2 = sameToken(a.link2) || link1;\n\n    var shape = a.shape && a.shape !== \"None\" ? a.shape : \"A, B; B, A\";\n    var tone = a.tone && a.tone !== \"None\" ? a.tone : \"\";\n    var anti = a.antimetabole === \"Strict\";\n\n    var effectsMode = a.effects === \"Add consequences\";\n    var eff1 = sameToken(a.effect1);\n    var eff2 = sameToken(a.effect2);\n\n    var proof1 = sameToken(a.proof1);\n    var proof2 = sameToken(a.proof2);\n\n    function requireTokens(){\n      if (!A || !B){ return \"- Add Token A and Token B to build the mirror.\"; }\n      return \"\";\n    }\n\n    function renderLine(){\n      if (!A || !B){ return \"-\"; }\n      var first = A + \" \" + link1 + \" \" + B;\n      var second = B + \" \" + link2 + \" \" + A;\n\n      if (anti){\n        // very strict reversal: reuse identical wording\n        first = A + \" \" + link1 + \" \" + B;\n        second = B + \" \" + link1 + \" \" + A;\n      }\n\n      if (effectsMode){\n        var tail1 = eff1 ? \" — \" + eff1 : \"\";\n        var tail2 = eff2 ? \" — \" + eff2 : \"\";\n        return first + tail1 + \"; \" + second + tail2 + \".\";\n      }\n      return first + \"; \" + second + \".\";\n    }\n\n    function snapMeter(){\n      if (!A || !B){ return null; }\n      var c1 = (A + \" \" + link1 + \" \" + B).length;\n      var c2 = (B + \" \" + (anti ? link1 : link2) + \" \" + A).length;\n      var diff = Math.abs(c1 - c2);\n      return \"Snap meter (clause lengths): \" + c1 + \" vs \" + c2 + \" chars (∆ \" + diff + \"). Aim for small deltas.\";\n    }\n\n    var variants = join([\n      \"- Antimetabole (strict): \" + (A && B ? (A + \" \" + link1 + \" \" + B + \"; \" + B + \" \" + link1 + \" \" + A + \".\") : \"(needs A and B)\"),\n      \"- Concessive twist: \" + (A && B ? (A + \" \" + link1 + \" \" + B + \", yet \" + B + \" \" + link2 + \" \" + A + \".\") : \"(needs A and B)\"),\n      \"- Principle form: \" + (A && B ? (\"Not \" + A + \", but \" + B + \"; not \" + B + \", but \" + A + \".\") : \"(needs A and B)\")\n    ]);\n\n    var qc = join([\n      \"- Identity: A and B are identical tokens across the mirror.\",\n      \"- Symmetry: clauses use parallel grammar and similar length.\",\n      \"- Plausibility: a skeptic would grant the reversal is meaningful.\",\n      \"- Evidence: one receipt per half if challenged.\"\n    ]);\n\n    var header = join([\n      \"Chiasmus — ABBA Builder\",\n      title ? \"Title: \" + title : null,\n      context ? \"Context: \" + context : null,\n      audience ? \"Audience: \" + audience : null,\n      tone ? \"Tone: \" + tone : null\n    ]);\n\n    var line = renderLine();\n    var warn = requireTokens();\n\n    var outPref = a.output_pref || \"Full worksheet\";\n    var lineOnly = outPref === \"Line only\";\n    var linePlus = outPref === \"Line + variants\";\n\n    return join([\n      header,\n      \"\",\n      \"# Line\",\n      line,\n      warn,\n      snapMeter(),\n      \"\",\n      lineOnly ? null : \"# Why it works\",\n      lineOnly ? null : \"- Reversal creates insight; symmetry aids memory; compression increases clarity.\",\n      \"\",\n      lineOnly || linePlus ? null : \"# How to craft\",\n      lineOnly || linePlus ? null : \"1) Pick two short twins (A and B).\",\n      lineOnly || linePlus ? null : \"2) Write the landing half first; then build the setup.\",\n      lineOnly || linePlus ? null : \"3) Keep grammar parallel; shorten nouns; sharpen verbs.\",\n      lineOnly || linePlus ? null : \"4) Tie each half to an effect; add one receipt per side.\",\n      \"\",\n      linePlus || lineOnly ? \"# Variants\" : \"# Variants and examples\",\n      variants,\n      lineOnly ? null : \"\",\n      lineOnly || linePlus ? null : \"# Field examples\",\n      lineOnly || linePlus ? null : \"- Tagline: Secure by default; default to secure.\",\n      lineOnly || linePlus ? null : \"- Research: We measure to understand; we understand to measure better.\",\n      lineOnly || linePlus ? null : \"- Policy: Protect rights to build trust; build trust to protect rights.\",\n      \"\",\n      lineOnly ? null : \"# Quality checklist\",\n      lineOnly ? null : qc,\n      \"\",\n      proof1 || proof2 ? \"# Receipts\" : null,\n      proof1 ? \"- First half: \" + proof1 : null,\n      proof2 ? \"- Second half: \" + proof2 : null\n    ]);\n  }",
