    "template": "(args = {}) => {\n    // ——— helpers\n    function T(s){ return String(s || \"\").trim(); }\n    function L(s){ return T(s).replace(/\\s+/g,\" \"); }\n    function lines(s){ return T(s).split(/\\n+/).map(v => L(v)).filter(Boolean); }\n    function bulletize(arr){ return (arr || []).filter(Boolean).map(v => \"- \" + v).join(\"\\n\"); }\n    function header(h){ return h ? (\"# \" + h) : \"\"; }\n    function emptyGuard(label, val){ return T(val) ? \"\" : (\"⚠️ Missing \" + label + \".\"); }\n\n    // ——— args\n    const title   = T(args.title);\n    const channel = args.channel || \"slide\";\n    const audience= T(args.audience);\n\n    const S = L(args.situation);\n    const C = L(args.complication);\n    const Q = L(args.question);\n    const A = L(args.answer);\n\n    const reasons = lines(args.reasons).slice(0, 3);\n    const risks   = lines(args.risks);\n    const owner   = T(args.owner);\n    const timeline= T(args.timeline);\n\n    const answerFirst   = String(args.answer_first || \"off\") === \"on\";\n    const addResolution = String(args.add_resolution || \"off\") === \"on\";\n    const tone          = args.tone || \"concise\";\n\n    // ——— quality checks\n    const checks = [];\n    if (S.length > 280) checks.push(\"Trim Situation to ≤2 lines.\");\n    if (!S) checks.push(\"Add a minimal, true Situation.\");\n    if (!C) checks.push(\"Name a single sharp Complication with stakes.\");\n    if (!Q) checks.push(\"Write the explicit Question that the Complication forces.\");\n    if (!A) checks.push(\"Answer in one governing line that directly resolves the Question.\");\n    if (reasons.length === 0) checks.push(\"List up to three supporting reasons under the Answer.\");\n    const hingeOK = (S && C && Q) ? \"\" : \"When S, then C, we must ask Q. If Q doesn’t feel inevitable from C, rewrite C or Q.\";\n\n    // ——— building blocks\n    const oneLine = [\n      S ? \"Situation: \\\"\" + S + \"\\\",\" : \"\",\n      C ? \"Complication: \\\"\" + C + \"\\\",\" : \"\",\n      Q ? \"Question: \\\"\" + Q + \"\\\",\" : \"\",\n      A ? \"Answer: \\\"\" + A + \".\\\"\" : \"\"\n    ].filter(Boolean).join(\" \");\n\n    const slideStack = [\n      \"## S — Situation\",\n      S || \"Add agreed facts and baseline metric.\",\n      \"\",\n      \"## C — Complication\",\n      C || \"What changed; why now; stakes.\",\n      \"\",\n      \"## Q — Question\",\n      Q || \"Binary / Choice / How-plan.\",\n      \"\",\n      \"## A — Answer (governing idea)\",\n      A || \"Your recommendation in one line.\",\n      reasons.length ? (\"\\n### Supports\\n\" + bulletize(reasons)) : \"\",\n      risks.length ? (\"\\n### Risks & mitigations\\n\" + bulletize(risks)) : \"\",\n      (owner || timeline) ? (\"\\n### Owner & timeline\\n- Owner: \" + (owner || \"TBD\") + \"\\n- Timeline: \" + (timeline || \"TBD\")) : \"\"\n    ].join(\"\\n\");\n\n    const emailOpen = [\n      \"**Situation:** \" + (S || \"…\"),\n      \"**Complication:** \" + (C || \"…\"),\n      \"**Question:** \" + (Q || \"…\"),\n      \"**Answer:** \" + (A || \"…\"),\n      reasons.length ? (\"\\n**Because:**\\n\" + bulletize(reasons)) : \"\",\n      risks.length ? (\"\\n**Risks / mitigations:**\\n\" + bulletize(risks)) : \"\",\n      (owner || timeline) ? (\"\\n**Owner / timeline:** \" + (owner || \"TBD\") + \" — \" + (timeline || \"TBD\")) : \"\"\n    ].join(\"\\n\");\n\n    const worksheet = [\n      \"## One-page SCQA worksheet\",\n      \"\",\n      \"**Situation (≤2 lines):** \" + (S || \"…\"),\n      \"**Complication (1 line + stakes):** \" + (C || \"…\"),\n      \"**Question (binary / choice / how):** \" + (Q || \"…\"),\n      \"**Answer (1 line):** \" + (A || \"…\"),\n      \"\",\n      \"### Three supports\",\n      reasons.length ? bulletize(reasons) : \"- 1) …\\n- 2) …\\n- 3) …\",\n      \"\",\n      \"### Risks & mitigations\",\n      risks.length ? bulletize(risks) : \"- Risk: … → Mitigation: …\",\n      \"\",\n      \"### Owner & timeline\",\n      \"- Owner: \" + (owner || \"TBD\"),\n      \"- Timeline: \" + (timeline || \"TBD\")\n    ].join(\"\\n\");\n\n    const resolutionSlot = addResolution ? \"\\n\\n## R — Resolution / Results\\nReport early outcomes or acceptance criteria once A is executed.\" : \"\";\n\n    // ——— answer-first variant\n    const answerFirstBlock = answerFirst\n      ? [\n          \"## Answer-first (exec view)\",\n          A ? A : \"Add the governing recommendation in one line.\",\n          reasons.length ? (\"\\n**Because:**\\n\" + bulletize(reasons)) : \"\",\n          \"\\n**Context → Tension → Question (for record):**\",\n          \"- Situation: \" + (S || \"…\"),\n          \"- Complication: \" + (C || \"…\"),\n          \"- Question: \" + (Q || \"…\")\n        ].join(\"\\n\")\n      : \"\";\n\n    // ——— output selector\n    const titleLine = title ? (header(title) + \"\\n\") : \"\";\n    const audienceLine = audience ? (\"**Audience:** \" + audience + \"\\n\\n\") : \"\";\n\n    let body = \"\";\n    if (channel === \"one-line\") {\n      body = oneLine;\n    } else if (channel === \"slide\") {\n      body = slideStack + resolutionSlot + (answerFirstBlock ? (\"\\n\\n\" + answerFirstBlock) : \"\");\n    } else if (channel === \"email\") {\n      body = (answerFirst ? (answerFirstBlock + \"\\n\\n\") : \"\") + emailOpen;\n    } else if (channel === \"memo\") {\n      body = (answerFirst ? (answerFirstBlock + \"\\n\\n\") : \"\") + slideStack + resolutionSlot;\n    } else { // worksheet (default if unknown)\n      body = worksheet;\n    }\n\n    const qc = [\n      \"### Quality checklist\",\n      checks.length ? bulletize(checks) : \"- Looks good. Ensure your Answer directly resolves the Question and governs the logic that follows.\",\n      hingeOK ? (\"\\n\" + hingeOK) : \"\"\n    ].join(\"\\n\");\n\n    const origin = [\n      \"### Notes\",\n      \"- SCQA = Situation → Complication → Question → Answer (Barbara Minto, *The Pyramid Principle*).\",\n      \"- Variants: Answer-first (exec), SCQR (Resolution/Results for case studies).\",\n      \"- Map to other tools: ABT (And=S, But=C, Therefore=A); PSP (Problem=C, Solution=A, Payoff=Results).\"\n    ].join(\"\\n\");\n\n    const toneNote = tone ? (\"**Tone:** \" + tone + \"\\n\\n\") : \"\";\n\n    // ——— final\n    return [\n      titleLine,\n      audienceLine,\n      toneNote,\n      body,\n      \"\\n\\n——\\n\",\n      qc,\n      \"\\n\\n\",\n      origin\n    ].join(\"\");\n  }",
