    "template": "(args = {}) => {\n    // Helpers\n    const T = v => String(v ?? \"\").trim();\n    const L = v => T(v).replace(/\\s+/g, \" \");\n    const lines = v => T(v).split(/\\n+/).map(s => s.trim()).filter(Boolean);\n    const bullets = arr => arr.map(s => \"- \" + s).join(\"\\n\");\n\n    // Inputs\n    const title   = T(args.title);\n    const audience= T(args.audience);\n    const channel = args.channel || \"one-pager\";\n    const tone    = args.tone || \"plain\";\n\n    const pratijna = L(args.pratijna);\n    const hetu     = L(args.hetu);\n    const udaharan = L(args.udaharan);\n    const upanaya  = L(args.upanaya);\n    const nigamana = L(args.nigamana);\n\n    const defeaters = lines(args.defeaters);\n    const evidence  = lines(args.evidence);\n\n    // Quality checks\n    const qc = [];\n    if (!pratijna) qc.push(\"Write Pratijñā (claim) with scope, time, and audience.\");\n    if (!hetu) qc.push(\"Add a single, relevant Hetu that actually indicates the claim (mechanism over vibes).\");\n    if (!udaharan) qc.push(\"State the general rule with a concrete Udāharaṇa (named exemplar + context).\");\n    if (!upanaya) qc.push(\"Bridge with Upanaya: show shared conditions and absence of defeaters.\");\n    if (!nigamana) qc.push(\"Close with Nigamana no stronger than your premises license.\");\n    if (pratijna && nigamana && nigamana.length > pratijna.length * 2)\n      qc.push(\"Tighten Nigamana; restate the licensed conclusion plainly.\");\n\n    // Blocks per channel\n    const onePager = [\n      title ? (\"# \" + title) : \"\",\n      audience ? (\"**Audience:** \" + audience + \"\\n\") : \"\",\n      \"**Nyāya five-part inference**\",\n      `1) **Pratijñā (Thesis):** ${pratijna || \"…\"}\\n`,\n      `2) **Hetu (Reason):** ${hetu || \"…\"}\\n`,\n      `3) **Udāharaṇa (Rule via example):** ${udaharan || \"…\"}\\n`,\n      `4) **Upanaya (Application / mapping):** ${upanaya || \"…\"}\\n`,\n      `5) **Nigamana (Conclusion):** ${nigamana || \"…\"}\\n`,\n      evidence.length ? (\"**Evidence links**\\n\" + bullets(evidence) + \"\\n\") : \"\",\n      defeaters.length ? (\"**Defeaters / fallacy scan**\\n\" + bullets(defeaters) + \"\\n\") : \"\",\n      \"### Notes\",\n      \"- **Vyāpti** (reliable concomitance) underwrites Udāharaṇa.\",\n      \"- Scan **Hetvābhāsa**: Savyabhicāra, Viruddha, Satpratipakṣa, Asiddha, Bādhita.\",\n      \"\",\n      \"### Quality checklist\",\n      (qc.length ? bullets(qc) : \"- Looks sound. Ensure Hetu ⇒ Pratijñā, Udāharaṇa is explicit, Upanaya maps conditions, Nigamana stays disciplined.\")\n    ].join(\"\\n\");\n\n    const slide = [\n      title ? (\"# \" + title) : \"# Nyāya Five-Part Syllogism\",\n      \"\",\n      \"## 1) Pratijñā (Thesis)\",\n      pratijna || \"We should do A in context C during T for G.\",\n      \"\",\n      \"## 2) Hetu (Reason / sign)\",\n      hetu || \"Because indicator/mechanism H is present.\",\n      \"\",\n      \"## 3) Udāharaṇa (Rule with example)\",\n      udaharan || \"Where H occurs, O follows, as in example E (cite).\",\n      \"\",\n      \"## 4) Upanaya (Mapping)\",\n      upanaya || \"Our case matches E on X, Y; no defeaters Z.\",\n      \"\",\n      \"## 5) Nigamana (Conclusion)\",\n      nigamana || \"Therefore A → O in C (this period).\",\n      \"\",\n      evidence.length ? (\"### Evidence\\n\" + bullets(evidence)) : \"\",\n      defeaters.length ? (\"\\n### Defeaters check\\n\" + bullets(defeaters)) : \"\",\n      \"\",\n      \"— Keep Nigamana within the license of 1-4.\"\n    ].join(\"\\n\");\n\n    const email = [\n      title ? (\"Subject: \" + title + \"\\n\") : \"\",\n      (audience ? (\"To: \" + audience + \"\\n\\n\") : \"\"),\n      \"Pratijñā — \" + (pratijna || \"…\"),\n      \"Hetu — \" + (hetu || \"…\"),\n      \"Udāharaṇa — \" + (udaharan || \"…\"),\n      \"Upanaya — \" + (upanaya || \"…\"),\n      \"Nigamana — \" + (nigamana || \"…\"),\n      evidence.length ? (\"\\nLinks:\\n\" + evidence.map((s,i)=> (i+1)+\". \"+s).join(\"\\n\")) : \"\",\n      defeaters.length ? (\"\\nDefeaters scan:\\n\" + defeaters.map((s,i)=> (i+1)+\". \"+s).join(\"\\n\")) : \"\"\n    ].join(\"\\n\");\n\n    const abstract = [\n      (title ? (title + \" — \") : \"\") + \"Nyāya five-step inference\",\n      `Pratijñā: ${pratijna || \"…\"}; Hetu: ${hetu || \"…\"}; Udāharaṇa: ${udaharan || \"…\"}; Upanaya: ${upanaya || \"…\"}; Nigamana: ${nigamana || \"…\"}.`\n    ].join(\"\\n\");\n\n    const body = channel === \"slide\" ? slide\n               : channel === \"email\" ? email\n               : channel === \"abstract\" ? abstract\n               : onePager;\n\n    const origin = [\n      \"### Origin / source\",\n      \"“Classical Indian philosophy of the Nyāya school. Core inferences appear in the Nyāya-sūtra (trad. Akṣapāda Gautama) with major commentaries by Vātsyāyana, Uddyotakara, Udayana, and later Navya-Nyāya (e.g., Gaṅgeśa).”\"\n    ].join(\"\\n\");\n\n    const mapping = [\n      \"### Mappings to familiar tools\",\n      \"- **Toulmin:** claim=Pratijñā; data=Hetu; warrant/backing=Udāharaṇa; application=Upanaya; claim restated=Nigamana.\",\n      \"- **Aristotle (major/minor):** Udāharaṇa≈major rule; Upanaya≈minor mapping; Nigamana≈conclusion.\",\n      \"- **SCQA:** use SCQA to open; place the five steps in the Answer.\"\n    ].join(\"\\n\");\n\n    return [\n      body,\n      \"\\n\\n---\\n\",\n      mapping,\n      \"\\n\\n\",\n      origin,\n      `\\n\\n**Tone:** ${tone}`\n    ].join(\"\");\n  }",
