    "template": "(args = {}) => {\n    const J = (xs) => (xs || []).filter(Boolean).join(\"\\n\");\n    const L = (h, xs) => xs && xs.length ? [h].concat(xs.map((x, i) => \"- \" + x)) : [];\n    const pick = (x, fallback) => (x && x !== \"None\" ? x : fallback);\n\n    const primary = pick(args.primary_rasa, \"adbhuta (wonder)\");\n    const supporting = pick(args.supporting_rasa, \"\");\n    const ctx = pick(args.context, \"Product onboarding\");\n    const audience = args.audience || \"Target audience not specified\";\n    const goal = args.goal || \"Define the single behavior/decision you want\";\n    const vibhava = args.vibhava || \"\";\n    const anubhava = args.anubhava || \"\";\n    const vyabhicari = args.vyabhicari || \"\";\n    const dhvani = args.dhvani || \"\";\n    const verbs = args.verbs || [];\n    const breakers = args.breakers || [];\n    const cta = args.cta || \"\";\n    const ethics = args.ethics || \"\";\n    const proof = args.proof || \"\";\n\n    return J([\n      \"Rasa–Dhvani Brief\",\n      \"\",\n      \"— Core —\",\n      \"Primary rasa: \" + primary,\n      supporting ? (\"Supporting rasa: \" + supporting) : \"\",\n      \"Context: \" + ctx,\n      \"Audience: \" + audience,\n      \"Goal: \" + goal,\n      \"\",\n      \"— Design the causes and signs —\",\n      vibhava && (\"Vibhāva (determinants/setting):\\n\" + vibhava),\n      anubhava && (\"Anubhāva (expressions/signs):\\n\" + anubhava),\n      vyabhicari && (\"Vyabhicāribhāva (supporting feelings):\\n\" + vyabhicari),\n      dhvani && (\"Dhvani cues (imply, don’t declare):\\n\" + dhvani),\n      J(L(\"Key verbs:\", verbs)),\n      J(L(\"Mood breakers to remove:\", breakers)),\n      \"\",\n      cta && (\"CTA (felt action): \" + cta),\n      ethics && (\"\\nInclusivity & ethics:\\n\" + ethics),\n      \"\",\n      \"— Fit & Evidence —\",\n      proof && proof,\n      !proof && \"Plan measures: teach-back of mood; intended action rate; language reuse; fewer clarifying questions.\",\n      \"\",\n      \"Notes:\",\n      \"- Keep one dominant mood; let any secondary support, not compete.\",\n      \"- Align visuals, typography, and pacing to the chosen mood.\",\n      \"- Replace one explicit claim with a vivid image that invites the same inference.\",\n      \"- Re-read for parallel verbs and remove mood-breaking words.\"\n    ]);\n  }",
