    "template": "(args = {}) => {\n    const J = (xs) => (xs || []).filter(Boolean).join(\"\\n\");\n    const L = (h, xs) => (xs && xs.length) ? [h].concat(xs.map(x => \"- \" + x)) : [];\n    const pick = (x, fb) => (x && x !== \"None\" ? x : fb);\n\n    const ctx = pick(args.context, \"Product/Program decision\");\n    const purpose = args.purpose || \"State the concrete decision you seek.\";\n    const participants = args.participants || [];\n    const order = pick(args.speaking_order, \"Junior to senior, then senior synthesis\");\n    const options = args.options || [];\n    const dissent = args.dissent_channels || [];\n    const rituals = args.rituals || [];\n    const face = args.face_saving || [];\n    const synth = args.synthesis_prompts || [];\n    const rule = args.decision_rule || \"Sponsor decides after round-robin by <date>.\";\n    const follow = args.followups || [];\n    const metrics = args.metrics || [];\n    const risks = args.risks || [];\n    const culture = args.cultural_notes || \"\";\n\n    return J([\n      \"Confucian Deliberation Plan — Harmony, Face, Ritual\",\n      \"\",\n      \"— Purpose & Context —\",\n      \"Context: \" + ctx,\n      \"Purpose: \" + purpose,\n      \"\",\n      \"— Participants & Roles —\",\n      J(L(\"Who’s in the room:\", participants)),\n      \"\",\n      \"— Before the Meeting —\",\n      \"- Send pre-reads with two or three viable options (pros/cons).\",\n      \"- Preview privately with key stakeholders; invite quiet pushback.\",\n      \"- Map titles and seating; prepare greetings and order of discussion.\",\n      J(L(\"Ritual signals (lǐ):\", rituals)),\n      J(L(\"Dissent channels:\", dissent)),\n      \"\",\n      \"— During the Meeting —\",\n      \"- Open with thanks, purpose, agenda, and time box.\",\n      \"Speaking order: \" + order,\n      J(L(\"Options to consider:\", options)),\n      J(L(\"Synthesis prompts (zhōngyōng):\", synth)),\n      J(L(\"Face-saving phrases at hand:\", face)),\n      \"\",\n      \"— Decision & Record —\",\n      \"Decision rule & deadline: \" + rule,\n      \"- Name the middle path if it integrates values (not just numbers).\",\n      \"- Credit contributors publicly; reject proposals with dignity.\",\n      \"\",\n      \"— After the Meeting —\",\n      J(L(\"Private follow-ups:\", follow)),\n      \"- Publish a respectful decision record (reasons, mitigations, owners, dates).\",\n      \"- Protect dignity in change management (coach in private).\",\n      \"\",\n      \"— Risks & Mitigations —\",\n      J(L(\"Identified risks:\", risks)),\n      \"\",\n      \"— Metrics of Success —\",\n      J(L(\"We will track:\", metrics.length ? metrics : [\n        \"Commitment and follow-through after decisions\",\n        \"Lower post-meeting escalation and public corrections\",\n        \"Participation breadth (unique contributors who spoke)\",\n        \"Dissent health (objections logged before, not after)\"\n      ])),\n      \"\",\n      \"— Cultural Notes —\",\n      culture || \"Add local norms: titles, gift customs, taboo topics, pacing, language preferences.\"\n    ]);\n  }",
