    "template": "(args = {}) => {\n    const J = (xs) => (xs || []).filter(Boolean).join(\"\\n\");\n    const L = (h, xs) => (xs && xs.length) ? [h].concat(xs.map(x => \"- \" + x)) : [];\n    const pick = (x, fb) => (x && (Array.isArray(x) ? x.length : true)) ? x : fb;\n\n    const partners = args.partners || [];\n    const purpose_dual = pick(args.purpose_dual, [\n      \"(Indigenous lens) …\",\n      \"(Western science lens) …\"\n    ]);\n    const protocols = args.protocols || [];\n    const sovereignty = args.sovereignty || \"OCAP (Ownership, Control, Access, Possession)\";\n    const data_agreements = args.data_agreements || [];\n    const ind = args.indicators_indigenous || [];\n    const sci = args.indicators_science || [];\n    const calendars = args.calendars || \"Align to community seasons and institutional windows.\";\n    const hires = args.community_hires || [];\n    const benefits = args.benefits || [];\n    const credit = args.credit || [];\n    const dispute = args.dispute || \"Joint council → mediation panel with community-appointed chair.\";\n    const reporting = args.reporting || [];\n    const decision_calendar = args.decision_calendar || \"Add seasonal and institutional dates with pause points.\";\n    const exit_pause = args.exit_pause || \"Community veto; protocol breach; harm detected.\";\n    const risks = args.risks || [];\n    const metrics = args.metrics || [];\n    const mou_links = args.mou_links || [];\n    const languages = args.languages || \"List working languages and accessibility supports.\";\n    const notes = args.notes || \"\";\n\n    return J([\n      \"Two-Eyed Seeing — Co-Governed Inquiry Plan\",\n      \"\",\n      \"— Partners & Authorities —\",\n      J(L(\"Circle:\", partners)),\n      \"\",\n      \"— Purpose in Both Lenses —\",\n      \"- \" + purpose_dual[0],\n      \"- \" + purpose_dual[1],\n      \"\",\n      \"— Protocols & Permissions —\",\n      J(L(\"Lived methods and approvals:\", protocols)),\n      \"\",\n      \"— Data Sovereignty & Agreements —\",\n      \"Model: \" + sovereignty,\n      J(L(\"Agreements:\", data_agreements)),\n      \"\",\n      \"— Dual Methods —\",\n      \"Indigenous lane (indicators & teachings):\",\n      J(L(\"\", ind)),\n      \"Science lane (instruments & models):\",\n      J(L(\"\", sci)),\n      \"Sampling & calendars: \" + calendars,\n      J(L(\"Community researchers (hiring & training):\", hires)),\n      \"\",\n      \"— Benefit-Sharing & Credit —\",\n      J(L(\"Benefit-sharing (budgeted):\", benefits)),\n      J(L(\"Co-authorship and credit:\", credit)),\n      \"\",\n      \"— Dispute Resolution —\",\n      dispute,\n      \"\",\n      \"— Reporting Outputs (Parallel Lanes) —\",\n      J(L(\"Formats, languages, venues:\", reporting)),\n      \"\",\n      \"— Decision Calendar —\",\n      decision_calendar,\n      \"\",\n      \"— Exit & Pause Conditions —\",\n      exit_pause,\n      \"\",\n      \"— Risks & Mitigations —\",\n      J(L(\"Plan for:\", risks)),\n      \"\",\n      \"— Success Metrics —\",\n      J(L(\"We will consider it working when:\", metrics.length ? metrics : [\n        \"Decisions are documented with community sign-off\",\n        \"OCAP/CARE audits pass\",\n        \"Community knowledge holders are named and compensated\",\n        \"Recommendations are implemented by both parties\",\n        \"Partners choose to continue collaborating\"\n      ])),\n      \"\",\n      \"— MOU / References —\",\n      J(L(\"Links / IDs:\", mou_links)),\n      \"\",\n      \"— Languages & Accessibility —\",\n      languages,\n      \"\",\n      \"— Transparency & Limits —\",\n      notes || \"Name uncertainties, divergences, and limits in both lenses.\",\n      \"\",\n      \"— Parallel Reporting Pattern (for your final deliverable) —\",\n      \"Indigenous lane: narratives, place-based indicators, teachings followed, permissions.\",\n      \"Science lane: methods, data, models, effect sizes, limitations.\",\n      \"Bridge lane: shared implications, actions, governance notes.\"\n    ]);\n  }",
