    "template": "(args = {}) => {\n    const J = (xs) => (xs || []).filter(Boolean).join(\"\\n\");\n    const L = (h, xs) => (xs && xs.length) ? [h].concat(xs.map(x => \"- \" + x)) : [];\n    const S = (x, fb) => (x && (Array.isArray(x) ? x.length : String(x).trim().length)) ? x : fb;\n\n    const partners = args.partners || [];\n    const purpose = S(args.purpose, \"Co-written purpose: …\");\n    const protocols = args.protocols || [];\n    const consent = args.consent || [];\n    const setting = S(args.setting, \"Community-hosted venue; time chosen with hosts; access and supports arranged.\");\n    const practice = S(args.practice, \"Indigenous Storywork (Sto:lo emphasis)\");\n    const prompts = args.prompts || [\n      \"What would you like decision-makers to understand first?\",\n      \"What has changed in this place, and how did you adapt?\",\n      \"What helps people show up, and what gets in the way?\"\n    ];\n    const care = args.care_plan || [];\n    const member_checking = S(args.member_checking, \"Story returns within 14 days; corrections welcomed before wider use.\");\n    const reciprocity = args.reciprocity || [];\n    const data_governance = S(args.data_governance, \"OCAP (Ownership, Control, Access, Possession)\");\n    const data_governance_details = S(args.data_governance_details, \"Community custodianship; access by council approval; withdrawal any time.\");\n    const docs = args.docs || [];\n    const analysis = args.analysis || [];\n    const outputs = args.outputs || [];\n    const differences = args.differences || [];\n    const timeline = S(args.timeline, \"Session dates aligned with community calendar; pause during ceremonies.\");\n    const risks = args.risks || [];\n    const metrics = args.metrics || [];\n    const contacts = args.contacts || [];\n\n    return J([\n      \"Indigenous Storywork — Session Plan\",\n      \"\",\n      \"— Partners & Authorities —\",\n      J(L(\"Circle and decision rights:\", partners)),\n      \"\",\n      \"— Purpose (Co-written) —\",\n      purpose,\n      \"\",\n      \"— Protocols & Openings —\",\n      J(L(\"Respectful forms:\", protocols)),\n      \"\",\n      \"— Consent & Data Options —\",\n      J(L(\"Ongoing, revocable:\", consent)),\n      \"\",\n      \"— Setting & Access —\",\n      setting,\n      \"\",\n      \"— Dialogue Practice —\",\n      \"Primary framing: \" + practice,\n      J(L(\"Practice-specific notes:\", differences)),\n      \"\",\n      \"— Prompts (Participant-led) —\",\n      J(L(\"\", prompts)),\n      \"\",\n      \"— Dignity & Care Plan —\",\n      J(L(\"Supports and pause/stop paths:\", care)),\n      \"\",\n      \"— Reciprocity & Compensation —\",\n      J(L(\"Give-back items:\", reciprocity)),\n      \"\",\n      \"— Data Governance —\",\n      \"Principles: \" + data_governance,\n      \"Details: \" + data_governance_details,\n      \"\",\n      \"— Documentation —\",\n      J(L(\"Field notes & recording:\", docs)),\n      \"\",\n      \"— Analysis —\",\n      J(L(\"Keep story arcs intact:\", analysis)),\n      \"\",\n      \"— Member Checking —\",\n      member_checking,\n      \"\",\n      \"— Outputs for Community Use —\",\n      J(L(\"Return formats:\", outputs)),\n      \"\",\n      \"— Timeline & Decision Calendar —\",\n      timeline,\n      \"\",\n      \"— Risks & Mitigations —\",\n      J(L(\"Plan for:\", risks)),\n      \"\",\n      \"— Success Metrics —\",\n      J(L(\"We will know it worked when:\", metrics.length ? metrics : [\n        \"Participants review and amend their stories before wider use\",\n        \"Trust indicators: fewer clarifying questions, more willing follow-ups\",\n        \"Actions changed as a result are documented and credited\",\n        \"Compensation and give-back delivered as promised\"\n      ])),\n      \"\",\n      \"— Contacts & Support —\",\n      J(L(\"\", contacts))\n    ]);\n  }",
